import unreal

# Check what materials the Niagara systems reference
for sys_name in ['NS_CRT_DotGrid', 'NS_DotGrid']:
    ns = unreal.load_asset(f"/Game/Niagara/{sys_name}")
    if ns:
        print(f"\n=== {sys_name} ===")
        print(f"Class: {ns.get_class().get_name()}")

        # Try to find material references via property inspection
        for prop in ['override_materials', 'material', 'sprite_material',
                     'mesh_material', 'default_material']:
            try:
                val = ns.get_editor_property(prop)
                print(f"  {prop}: {val}")
            except: pass

# Also check: are any assets in the project referencing these materials?
for mat_name in ['M_CRT_Dot', 'M_CRT_Dot_Off', 'M_CRT_Pink']:
    mat = unreal.load_asset(f"/Game/Materials/{mat_name}")
    if not mat:
        mat = unreal.load_asset(f"/Game/Materials/Dots/{mat_name}")
    if mat:
        # Find referencers
        registry = unreal.AssetRegistryHelpers.get_asset_registry()
        refs = registry.get_referencers(mat.get_path_name())
        print(f"\n{mat_name} referenced by: {list(refs) if refs else 'nothing'}")
    else:
        print(f"\n{mat_name}: not found at original path (user moved to Dots folder)")

